custom_defined_behaviors:
behaviors {
  gr_au: graphite_apostrophe_underscore {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp APOSTROPHE>, <&kp UNDERSCORE>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
  gr_cm: graphite_comma_question_mark {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp COMMA>, <&kp QUESTION>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
  gr_pd: graphite_period_greater_than {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp PERIOD>, <&kp GREATER_THAN>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
  gr_fs: graphite_forward_slash_less_than {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp FSLH>, <&kp LESS_THAN>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
  gr_mi: graphite_minus_double_quote {
    compatible = "zmk,behavior-mod-morph";
    #binding-cells = <0>;
    bindings = <&kp MINUS>, <&kp DOUBLE_QUOTES>;
    mods = <(MOD_LSFT|MOD_RSFT)>;
  };
};

